// Build one personalized email per user.
//
// DEMO SAFETY (assignment requirement): never email the real sample-CSV
// addresses. Every message is redirected to a safe TEST inbox. Set the n8n env
// var DEMO_INBOX (e.g. 'abcd+loan@gmail.com'); we also tag the alias with the
// user_id so you can see which user each mail was for. Set DEMO_REDIRECT=off to
// send to the real address (do NOT do this with the sample data).
const items = $input.all();
const redirect = ($env.DEMO_REDIRECT || 'on').toLowerCase() !== 'off';
const demoInbox = $env.DEMO_INBOX || 'abcd+loan@gmail.com';
const sender = $env.SES_SENDER || 'loan-engine@example.com';

function aliasFor(userId) {
  // abcd+loan@gmail.com -> abcd+loan-<userId>@gmail.com (gmail +aliasing)
  const at = demoInbox.indexOf('@');
  if (at < 0) return demoInbox;
  const local = demoInbox.slice(0, at);
  const domain = demoInbox.slice(at);
  const safeId = String(userId).replace(/[^A-Za-z0-9]/g, '').slice(0, 12);
  return (local.includes('+') ? `${local}-${safeId}` : `${local}+${safeId}`) + domain;
}

function fmtRate(p) {
  if (p.interest_rate_min == null && p.interest_rate_max == null) return '';
  if (p.interest_rate_max == null) return ` — from ${p.interest_rate_min}% p.a.`;
  return ` — ${p.interest_rate_min}%–${p.interest_rate_max}% p.a.`;
}

const out = [];
for (let idx = 0; idx < items.length; idx++) {
  const it = items[idx];
  const u = it.json;
  const products = Array.isArray(u.products) ? u.products : [];
  if (products.length === 0) continue;

  const lines = products.map(p => {
    const lender = p.lender_name ? `${p.lender_name} — ` : '';
    return `• ${lender}${p.product_name}${fmtRate(p)}`;
  });

  const greeting = u.name ? `Hi ${u.name},` : 'Hello,';
  const textBody = `${greeting}\n\n` +
    `Good news — based on your profile you may qualify for ${products.length} personal loan product(s):\n\n` +
    lines.join('\n') +
    `\n\nThese are indicative matches, not an offer or approval. Terms are set by each lender.\n\n— The Loan Eligibility Engine`;

  const htmlItems = products.map(p => {
    const lender = p.lender_name ? `<strong>${p.lender_name}</strong> — ` : '';
    return `<li>${lender}${p.product_name}${fmtRate(p)}</li>`;
  }).join('');
  const htmlBody = `<p>${greeting}</p>` +
    `<p>Good news — based on your profile you may qualify for <strong>${products.length}</strong> personal loan product(s):</p>` +
    `<ul>${htmlItems}</ul>` +
    `<p style="color:#666;font-size:12px">These are indicative matches, not an offer or approval. Terms are set by each lender.</p>` +
    `<p>— The Loan Eligibility Engine</p>`;

  const toAddress = redirect ? aliasFor(u.user_id) : u.email;

  out.push({ json: {
    user_id: u.user_id,
    original_email: u.email,
    to: toAddress,
    from: sender,
    subject: `You have ${products.length} personal loan match${products.length === 1 ? '' : 'es'}`,
    text: textBody,
    html: htmlBody,
    product_count: products.length,
    redirected: redirect
  }, pairedItem: { item: idx } });
}
return out;
